import {foundations} from './foundations.js';
import {aiFoundations} from './ai-foundations.js';
import {globalBackend} from './global-backend.js';
export const ENGINEERING_VERSION='engineering-2026-11-independent-v2';
export const stages=[
 ['Fundamentos de ingeniería','Razonar sobre integridad, responsabilidades y fallos.'],
 ['Backend profesional','Construir servicios con contratos claros y límites comprobables.'],
 ['Bases de datos a escala','Modelar, medir y operar datos con garantías explícitas.'],
 ['Sistemas distribuidos','Coordinar procesos que fallan de forma independiente.'],
 ['Inteligencia artificial aplicada','Integrar modelos con evidencia, herramientas y evaluación.'],
 ['Automatización inteligente','Orquestar flujos recuperables con permisos acotados.'],
 ['Arquitectura y producción','Desplegar, observar y operar sistemas confiables.'],
 ['Proyecto empresarial','Integrar la plataforma y defender sus decisiones.'],
].map(([title,goal],i)=>({number:i+1,title,goal}));
stages.unshift({number:0,title:'Empieza desde cero',goal:'Comprende un sistema completo antes de profundizar en sus herramientas.'});
// Each concept combines a technical explanation, a scenario and competing decisions.
const concept=(name,explanation,prompt,correct,a,b,why,critical=false)=>({name,explanation,prompt,options:[correct,a,b],answer:0,why,critical});
const entries=[];
function lesson(stage,title,goal,concepts,code,flow,caseStudy,task,debug){entries.push({stage,title,goal,concepts,code,flow,caseStudy,task,debug});}
lesson(1,'Una operación, un efecto: idempotencia y Outbox','Demostrar que una solicitud repetida o un worker reiniciado no duplica un efecto.',[
 concept('Idempotencia','Un reintento no es una nueva intención de negocio. Una clave de idempotencia representa una operación dentro del alcance de un cliente. La garantía se materializa en una restricción única y una transacción, no en una consulta previa. Guarda una huella del payload: la misma clave con contenido distinto debe rechazarse.','Dos peticiones concurrentes cobran la misma orden. ¿Qué diseño protege el registro local?','Restricción única por cliente y clave, transacción y respuesta persistida','SELECT antes del INSERT sin restricción','Un Set en el navegador','La restricción arbitra también entre procesos concurrentes; la consulta previa deja una carrera.',true),
 concept('Atomicidad y Outbox','Una transacción local puede guardar el cambio de negocio y su evento Outbox juntos. No puede hacer atómicos por sí sola un COMMIT de Postgres y una publicación en RabbitMQ. Un publicador posterior lee eventos pendientes. Si publica y se cae antes de marcar, puede repetir: el consumidor todavía necesita deduplicar.','¿Cómo evitas confirmar una orden y perder su evento por una caída?','Guardar orden y evento Outbox en la misma transacción','Confirmar la orden y luego intentar publicar sin registro','Publicar antes del COMMIT y asumir éxito','El Outbox elimina la ventana de pérdida entre dos escrituras independientes.',true),
 concept('Workers y recuperación','Entrega al menos una vez significa que un mensaje puede reaparecer. El worker confirma el mensaje después de persistir el efecto. Si una API externa participa, utiliza su mecanismo de idempotencia y reconciliación: la transacción local no puede deshacer un cobro remoto.','El worker persiste y cae antes del ACK. ¿Qué esperas al reiniciarlo?','Reentrega y deduplicación del mismo efecto','Garantía universal de exactamente una ejecución','Pérdida obligatoria del registro persistido','La ventana entre commit y ACK produce duplicados de entrega, no debe producir duplicados de negocio.',true),
 concept('Pruebas de concurrencia','La prueba relevante ejecuta solicitudes en paralelo con la misma clave y simula fallos antes y después del COMMIT y del ACK. Verifica una sola operación durable y estados recuperables. Una prueba con una sola llamada no demuestra ausencia de carreras.','¿Qué prueba aporta evidencia de integridad?','Llamadas paralelas y caída tras commit, verificando una sola operación','Revisar solo que la respuesta HTTP sea 200','Probar una petición manual sin consultar la base','La evidencia debe comprobar invariantes bajo los fallos que se pretenden tolerar.'),
],`-- Dentro de una única transacción local\nINSERT INTO operations (tenant_id, idem_key, payload_hash)\nVALUES ($1, $2, $3)\nON CONFLICT (tenant_id, idem_key) DO NOTHING;\n-- Si ya existe: comprobar payload_hash y devolver su resultado.\n-- Si se insertó: crear orden y evento Outbox en la misma transacción.\nINSERT INTO outbox (event_id, payload) VALUES ($4, $5);\n-- COMMIT. El publicador puede reintentar; el consumidor deduplica.`,['Validar identidad y payload','Reclamar clave única y guardar orden + Outbox','Confirmar transacción','Publicar y procesar con deduplicación'],
 'Una plataforma concilia pagos de dos proveedores. El cliente pierde la respuesta y reintenta mientras otro proceso recibe el webhook. Ambos representan el mismo pago y deben compartir una identidad de negocio verificable.',
 'Diseña tablas y restricciones para orden, clave idempotente, Outbox y deduplicación del consumidor. Explica qué ocurre si el proceso cae después de cada paso. Incluye una prueba concurrente y cómo reconciliarías una API de cobros externa.',
 {code:'if (!(await exists(key))) { await insertPayment(key); }',question:'¿Qué defecto de concurrencia tiene este código?',options:['La consulta y la inserción dejan una carrera; falta una restricción única durable','await garantiza exclusión entre todos los procesos','El fallo se arregla guardando la clave en React'],answer:0,why:'Dos transacciones pueden observar ausencia al mismo tiempo. La base debe arbitrar la unicidad.'});
lesson(1,'Contratos, responsabilidades y acceso','Separar autenticación, autorización y reglas del dominio.',[
 concept('Límites de responsabilidad','La interfaz expresa intención; el servidor valida permisos y reglas; la base impone invariantes. Un controlador traduce HTTP y delega el caso de uso. SOLID ayuda a separar motivos de cambio: un servicio que cobra, renderiza HTML y envía correo tiene demasiadas responsabilidades.','¿Dónde verificas que alguien puede consultar una factura?','En el servidor, contra el propietario o permiso del recurso','Solo ocultando un botón','Confiando en userId recibido en el body','Una interfaz modificable no es un control de acceso.',true),
 concept('REST y contratos','Diseña recursos y códigos de estado antes de los handlers. Un contrato describe entradas, salidas, errores y efectos. Validar forma no sustituye validar negocio: un entero positivo todavía puede referirse a una orden ajena.','Un JSON tiene la forma correcta pero accede a una cuenta ajena. ¿Qué falta?','Autorización sobre el recurso','Solo TypeScript en el frontend','Más campos opcionales','La validez estructural y el permiso son controles distintos.',true),
 concept('Capas y patrones','Una capa de aplicación coordina; el dominio decide; un adaptador integra infraestructura. Strategy puede aislar proveedores de pago, pero no hace falta una jerarquía por cada función. Evalúa si hay variación real y pruebas que justifiquen la abstracción.','¿Cuándo aporta Strategy para pagos?','Cuando varios proveedores implementan la misma capacidad con variaciones reales','Cuando deseas añadir clases aunque solo haya un caso trivial','Para evitar validar respuestas externas','El patrón encapsula variación concreta, no sustituye reglas ni contratos.'),
 concept('Amenazas de confianza','Una credencial prueba identidad, no autorización universal. No aceptes roles elegidos por el cliente y nunca almacenes contraseñas en texto plano. Limita la respuesta al mínimo de datos necesarios.','Un registro público incluye role=admin. ¿Qué haces?','Ignorar o rechazar ese rol y asignar privilegios en el servidor','Confiar en el formulario','Firmar el rol enviado sin comprobarlo','El límite de confianza impide que el cliente se otorgue permisos.',true),
],`async function getInvoice(actor, id) {\n  const invoice = await repository.find(id);\n  if (!invoice || invoice.ownerId !== actor.id) throw notFound();\n  return { id: invoice.id, total: invoice.total };\n}`,['Autenticar','Validar entrada','Autorizar recurso','Ejecutar caso de uso'],
 'Un portal empresarial atiende varias compañías. Un administrador de una empresa no puede ver facturas de otra cambiando un identificador.',
 'Propón un endpoint REST, su contrato de errores y una prueba de acceso cruzado entre dos empresas. Explica qué colocarías en controlador, aplicación y repositorio.',
 {code:'const invoice = await db.invoice.find(req.body.id); return invoice;',question:'¿Qué falta antes de devolver la factura?',options:['Comprobar autorización del actor sobre la factura y limitar campos','Comprobar únicamente que id no está vacío','Ocultar el endpoint en el menú'],answer:0,why:'Un identificador válido no demuestra pertenencia.'});
lesson(1,'Estados, observabilidad y pruebas de fallo','Convertir un proceso implícito en transiciones verificables.',[
 concept('Máquinas de estados','Un estado representa hechos confirmados, no deseos. Define transiciones permitidas, precondiciones y terminales. Evita combinaciones incoherentes de booleanos como paid=true y canceled=true sin una regla de resolución.','¿Cómo impides pasar una orden cancelada a enviada?','Con una transición validada y una actualización condicional','Cambiando el texto de un botón','Añadiendo más booleanos sin reglas','La transición debe comprobarse al escribir el estado.'),
 concept('Logs, métricas y trazas','Los logs detallan eventos, las métricas agregan comportamiento y las trazas relacionan operaciones. Un correlationId une API, Outbox y worker. No registres tokens ni datos sensibles; un identificador técnico suele bastar.','¿Qué información ayuda a seguir una orden sin exponer credenciales?','Identificador de correlación, estado y duración','El token completo en cada log','La contraseña del usuario','La observabilidad no debe convertirse en una fuga de secretos.',true),
 concept('Pruebas de integración','Comprueba contratos entre componentes reales, especialmente restricciones y transacciones. Una base falsa que no aplica índices únicos no revela los mismos fallos que Postgres. Mantén los datos de prueba aislados.','¿Qué prueba valida una restricción única?','Dos inserciones contra una base con esa restricción','Un mock que siempre responde éxito','Una captura de pantalla del formulario','Hay que probar la garantía en la capa que la implementa.'),
 concept('Diagnóstico','Parte del síntoma, formula una hipótesis y busca evidencia que pueda refutarla. Una cola creciente puede señalar saturación, mensajes tóxicos o una dependencia lenta. Reiniciar sin observar puede ocultar el problema.','La cola crece y el proveedor responde lentamente. ¿Qué revisarías primero?','Tasas de entrada/salida, latencia y errores del proveedor','El color del dashboard','Eliminar todos los mensajes','Las señales deben distinguir saturación de fallos permanentes.'),
],`UPDATE jobs SET state='running'\nWHERE id=$1 AND state='pending'\nRETURNING id;\n-- Cero filas: otro proceso ganó o la transición no es válida.`,['Observar síntoma','Formular hipótesis','Reproducir con evidencia','Validar corrección'],
 'Un conciliador deja operaciones pendientes. Debes distinguir entre una caída, un proveedor lento y una transición inválida.',
 'Dibuja la máquina de estados de una conciliación. Define tres métricas, dos pruebas de fallos y cómo investigarías un estado atascado.',
 {code:'job.state = "done"; await callProvider();',question:'¿Qué es incorrecto?',options:['Se marca un éxito antes de confirmar el efecto','Es obligatorio marcar éxito antes de trabajar','Los estados no necesitan persistencia'],answer:0,why:'La observabilidad y el estado deben representar hechos confirmados.'});
lesson(2,'TypeScript y el runtime de Node','Distinguir garantías estáticas de validación y ejecución.',[
 concept('Tipos y validación','TypeScript comprueba el código antes de ejecutarlo; el JSON externo llega sin esas garantías. Recibe unknown, valida su estructura y convierte al tipo del dominio. Un cast no transforma ni valida un valor.','¿Qué protege la entrada de una API?','Validación de runtime antes de usar los datos','Un cast as User','Una interfaz solo en React','Los tipos se borran y no validan datos externos.',true),
 concept('Event loop','Node puede coordinar muchas operaciones de I/O, pero una función CPU-intensiva bloquea el hilo que ejecuta JavaScript. async no mueve automáticamente el cálculo a otro núcleo. Usa workers o jobs para tareas pesadas.','¿Dónde ejecutarías un cálculo CPU intensivo largo?','En un worker con límites y seguimiento','En un bucle síncrono dentro del handler','En una función async sin cambiar el cálculo','La concurrencia de I/O no elimina el coste de CPU.'),
 concept('Errores y recursos','Captura errores donde puedes añadir contexto o traducirlos. Usa finally para liberar conexiones. Distingue un error de validación de uno temporal; reintentar un payload inválido consume capacidad sin ayudar.','¿Qué error no debe reintentarse sin cambiar la entrada?','Un campo obligatorio inválido','Un timeout temporal','Un bloqueo transitorio recuperable','Un error permanente requiere corregir su causa.'),
 concept('NestJS y estructura','Módulos, providers e inyección permiten separar dependencias. Usa guards para acceso, pipes para validar y servicios para casos de uso. El framework organiza, pero no garantiza por sí mismo permisos ni transacciones.','¿Qué responsabilidad encaja en un guard?','Comprobar acceso del actor','Elegir colores de React','Reemplazar índices de la base','Un guard protege límites de ejecución.'),
],`function parseAmount(value: unknown): number {\n  if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) {\n    throw new Error('Importe inválido');\n  }\n  return value;\n}`,['Recibir unknown','Validar en runtime','Convertir al dominio','Ejecutar caso de uso'],
 'Una importación de archivos compite con solicitudes interactivas. Necesitas evitar bloquear el API y devolver errores útiles por fila.',
 'Diseña un endpoint que valide una solicitud de importación y envíe el trabajo pesado a un worker. Explica qué garantizan los tipos y qué no.',
 {code:'const amount = req.body.amount as number;',question:'¿Qué garantiza este cast?',options:['Solo una afirmación al compilador, sin validar runtime','Que el cliente envió un número positivo','Que nunca llegará null'],answer:0,why:'El cast no ejecuta una comprobación.'});
lesson(2,'Arquitectura limpia y hexagonal','Aislar el dominio sin crear abstracciones vacías.',[
 concept('Puertos y adaptadores','Un puerto describe una necesidad del caso de uso; un adaptador la implementa para una tecnología. El dominio no debería depender de los detalles HTTP de un proveedor. Conserva un contrato común, no una copia de cada SDK.','¿Qué debe conocer el caso de uso?','Un puerto de la capacidad requerida','La estructura interna de cada SDK','El estado del menú de React','Una interfaz estable reduce acoplamiento.'),
 concept('Validación de negocio','Validar un email es distinto de decidir si una orden puede cancelarse. La segunda regla pertenece al dominio y debe aplicarse aunque la operación llegue por worker, API o consola.','¿Dónde ubicas la regla de cancelación?','En el dominio compartido por las entradas','Solo en un formulario','Dentro de un componente visual','Los caminos alternativos no deben saltarse la regla.'),
 concept('Errores de aplicación','Traduce errores técnicos a categorías con significado: no encontrado, conflicto, temporal. No entregues stack traces o credenciales al cliente. Guarda contexto técnico seguro para diagnóstico.','Un proveedor devuelve un error interno. ¿Qué expones?','Un error controlado y un identificador de soporte','El token del proveedor','Toda la respuesta sin filtrar','El contrato externo no debe filtrar detalles privados.',true),
 concept('Pragmatismo','Una abstracción tiene coste de navegación, pruebas y evolución. Comienza con módulos claros y extrae puertos donde hay límites reales. No necesitas microservicios para aplicar separación de responsabilidades.','¿Qué harías en un producto pequeño con un solo equipo?','Un monolito modular con límites claros','Un servicio por cada clase','Una cola entre todas las funciones','La complejidad debe resolver una necesidad observada.'),
],`interface Payments {\n  charge(input: ChargeInput): Promise<ChargeResult>;\n}\nclass Checkout {\n  constructor(private payments: Payments) {}\n  run(input: ChargeInput) { return this.payments.charge(input); }\n}`,['Definir caso de uso','Definir puerto','Implementar adaptador','Probar contrato'],
 'La empresa cambiará de proveedor de cobros. Las reglas de autorización y de estado de la orden deben permanecer iguales.',
 'Define un puerto de pagos y dos adaptadores. Describe cómo probarías el caso de uso sin red y cómo validarías cada adaptador contra un contrato real.',
 {code:'class DomainOrder extends VendorPaymentSDK {}',question:'¿Qué acoplamiento introduce?',options:['El dominio depende de una implementación externa','Un puerto independiente del proveedor','Separación automática de responsabilidades'],answer:0,why:'La herencia hace que el dominio conozca detalles de infraestructura.'});
lesson(2,'APIs externas seguras y comprobables','Integrar dependencias sin perder control de errores y permisos.',[
 concept('Contratos de integración','Define timeout, formato, errores y semántica de reintento. Una respuesta 200 con JSON inesperado puede ser un fallo de contrato. Valida la respuesta y no propagues ciegamente datos de terceros.','¿Qué haces con un 200 cuyo JSON no cumple el contrato?','Tratarlo como fallo de integración controlado','Asumir éxito por el código HTTP','Guardar cualquier contenido como válido','El éxito de transporte no demuestra éxito de negocio.'),
 concept('Seguridad de salida','No permitas que el usuario elija una URL arbitraria para una llamada privilegiada. Valida destinos y evita acceso a redes internas. Los secretos quedan en servidor, nunca en VITE_* ni en el navegador.','¿Dónde debe vivir una clave privada de proveedor?','En configuración de servidor protegida','En el bundle de React','En un parámetro de URL público','El cliente no es un almacén de secretos.',true),
 concept('Pruebas de contrato','Un mock ayuda a probar una rama de error; una prueba de contrato comprueba que el adaptador interpreta al proveedor. Simula latencia, respuestas malformadas y duplicados, además del camino feliz.','¿Qué conjunto detecta más fallos de integración?','Éxito, timeout, JSON inválido y respuesta duplicada','Solo un mock de éxito','Solo verificar que se ejecutó fetch','Las pruebas deben cubrir los límites de confianza y fallo.'),
 concept('Versionado','Evoluciona contratos de forma compatible cuando sea posible. Agregar un campo opcional suele ser distinto de renombrar uno obligatorio. Usa pruebas de consumidores y periodos de migración para cambios incompatibles.','¿Qué cambio requiere revisar compatibilidad?','Eliminar un campo obligatorio usado por consumidores','Agregar un campo opcional documentado','Mejorar un comentario interno','Los consumidores existentes dependen del contrato acordado.'),
],`const response = await fetch(allowedUrl, {\n  signal: AbortSignal.timeout(3000),\n  headers: { Authorization: 'Bearer ' + serverSecret }\n});\nif (!response.ok) throw new IntegrationError(response.status);\nconst data = validateProviderResponse(await response.json());`,['Autorizar intención','Validar destino y solicitud','Llamar con timeout','Validar y traducir respuesta'],
 'Una integración crea pólizas. Un timeout deja incierto si se emitió la póliza; repetir sin una clave estable puede duplicar la operación.',
 'Diseña el contrato del adaptador, errores y reconciliación posterior a un timeout. Incluye pruebas de datos malformados y un intento de SSRF.',
 {code:'fetch(req.body.url, {headers: {Authorization: secret}})',question:'¿Qué riesgo crea?',options:['Enviar secretos a un destino controlado por el usuario','Una política de destinos segura','Autorización automática del proveedor'],answer:0,why:'El destino arbitrario puede exfiltrar secretos o acceder a servicios internos.'});
lesson(3,'Modelado, índices y planes de ejecución','Diseñar datos para consultas e invariantes concretos.',[
 concept('Modelo e invariantes','El modelo representa identidades, relaciones y estados. Claves foráneas y restricciones únicas protegen hechos incluso con múltiples aplicaciones. Elige tipos apropiados para dinero y fechas y documenta el significado de cada campo.','¿Qué protege una relación obligatoria entre orden y cliente?','Una clave foránea y un campo no nulo','Un comentario en React','Un índice sin relación','El dato debe ser válido en la base, no solo en una pantalla.'),
 concept('Índices','Un índice acelera ciertos accesos a cambio de almacenamiento y trabajo por escritura. El orden de columnas debe responder al filtro y al orden solicitado. No indexar todo ni asumir que un índice siempre será usado.','Filtras por empresa y ordenas por fecha. ¿Qué investigarías?','Un índice compuesto coherente con filtro y orden','Un índice aleatorio en cada columna','Eliminar todos los índices','El patrón de acceso guía el diseño del índice.'),
 concept('EXPLAIN','El plan estimado explica decisiones del optimizador. EXPLAIN ANALYZE ejecuta la consulta: puede modificar datos si se aplica a una escritura. Revisa filas estimadas y reales, bucles, tiempo y buffers, con datos representativos.','¿Qué precaución exige EXPLAIN ANALYZE sobre un UPDATE?','Que realmente ejecuta la escritura','Que nunca ejecuta cambios','Que no necesita permisos','Es una medición por ejecución, no una simulación.',true),
 concept('Medición','Optimiza una consulta frecuente o costosa demostrada por evidencia. Un escaneo secuencial sobre una tabla pequeña puede ser óptimo. Prueba antes/después y observa latencia y coste de escritura, no solo una ejecución aislada.','¿Cuándo aceptarías un escaneo secuencial?','Cuando el volumen y selectividad justifican su coste','Nunca, aunque la tabla tenga diez filas','Solo si todos los campos son texto','La elección depende de cardinalidad y selectividad.'),
],`CREATE INDEX orders_tenant_created_idx\nON orders (tenant_id, created_at DESC);\nEXPLAIN (ANALYZE, BUFFERS)\nSELECT id, total FROM orders\nWHERE tenant_id = 42 ORDER BY created_at DESC LIMIT 50;`,['Definir consulta y volumen','Observar plan','Proponer índice','Medir lectura y escritura'],
 'Un dashboard consulta las últimas órdenes de una compañía sobre millones de filas.',
 'Modela la relación empresa-orden. Propón un índice y un experimento reproducible con EXPLAIN, incluyendo el coste adicional de escritura.',
 {code:'SELECT * FROM orders; // para mostrar las últimas 50',question:'¿Qué problema hay?',options:['Se recuperan filas y columnas que la interfaz no necesita','La consulta limita automáticamente a 50','Un índice evita toda transferencia'],answer:0,why:'Hay que limitar y proyectar explícitamente.'});
lesson(3,'Aislamiento, bloqueos y dinero','Mantener invariantes cuando varias transacciones compiten.',[
 concept('Aislamiento','Una transacción no elimina todas las anomalías. El nivel de aislamiento define qué observaciones y conflictos son posibles. En SERIALIZABLE pueden aparecer abortos que requieren reintentar toda la unidad de trabajo.','¿Qué debes prever con SERIALIZABLE?','Reintentos de transacciones abortadas por serialización','Ausencia absoluta de errores','Bloqueos en el navegador','La base puede abortar para conservar el orden serializable.'),
 concept('Actualización atómica','Leer saldo, calcular en memoria y escribir deja carreras si no hay protección. Una actualización condicional puede verificar saldo y descontar en una operación. Comprueba las filas afectadas.','¿Qué evita descontar si no hay saldo suficiente?','UPDATE condicional y comprobación de RETURNING','SELECT y escritura sin control','Una variable global','La condición se aplica de forma atómica en la escritura.',true),
 concept('Bloqueos','Los bloqueos coordinan acceso a filas; su alcance y duración importan. Adquiere recursos en orden consistente y evita llamar APIs externas mientras mantienes una transacción abierta innecesariamente.','¿Qué aumenta el riesgo de deadlock?','Adquirir las mismas filas en órdenes opuestos','Mantener un orden fijo de acceso','Transacciones cortas','Los ciclos de espera surgen con órdenes incompatibles.'),
 concept('Representación','No uses coma flotante binaria sin una política para cálculos monetarios exactos. Define moneda, precisión y redondeo. Un entero de unidades mínimas funciona cuando la moneda y el alcance lo permiten; numeric es otra opción.','¿Qué decisión debes documentar al guardar dinero?','Moneda, precisión y regla de redondeo','Solo el color del recibo','Que cualquier float es siempre exacto','El tipo no sustituye las reglas monetarias.'),
],`UPDATE wallets SET balance_cents = balance_cents - $1\nWHERE id=$2 AND balance_cents >= $1\nRETURNING balance_cents;\n-- Cero filas: no se aplicó el débito. Validar importe positivo antes.`,['Validar importe e identidad','Abrir transacción','Aplicar escrituras protegidas','Confirmar o reintentar conflicto'],
 'Dos workers intentan debitar una billetera al mismo tiempo. El saldo nunca debe ser negativo.',
 'Describe una solución con UPDATE condicional y otra con bloqueo de fila. Compara duración de bloqueos y prueba dos débitos concurrentes.',
 {code:'const b=await readBalance(); await writeBalance(b-amount);',question:'¿Qué anomalía puede aparecer?',options:['Actualización perdida o violación del saldo bajo concurrencia','Exclusión mutua automática','Serialización por usar await'],answer:0,why:'await solo ordena esa ejecución local.'});
lesson(3,'Millones de filas: lotes y evolución','Procesar y migrar datos sin bloquear toda la operación.',[
 concept('Lotes','Divide el trabajo en lotes medidos y con checkpoints durables. Evita cargar millones de filas en memoria. Una transacción gigantesca amplía bloqueos, retención y coste de recuperación.','¿Cómo procesas un conjunto enorme?','Lotes acotados con progreso persistido','Un array con todos los registros','Una transacción sin límites de tiempo','Los límites hacen el proceso observable y recuperable.'),
 concept('Paginación','La paginación por cursor usa una clave estable y orden total. OFFSET creciente puede volverse costoso y cambia bajo inserciones. Un cursor basado en fecha e ID resuelve empates.','¿Qué necesita un cursor confiable?','Orden estable con desempate único','Solo una fecha que puede repetirse','Orden aleatorio por página','Sin orden total puedes omitir o repetir filas.'),
 concept('Particiones y réplicas','Particionar ayuda a gestionar conjuntos y podar consultas compatibles; no acelera cualquier filtro. Una réplica puede reducir carga de lecturas, pero tener retraso. Las lecturas que requieren el último dato deben considerar esa consistencia.','¿Qué riesgo tiene leer una réplica tras una escritura?','Ver datos atrasados','Modificar automáticamente el primario','Garantía universal de lectura inmediata','La replicación puede no haber aplicado el cambio aún.'),
 concept('Migraciones','Usa expandir-migrar-contraer: añade compatibilidad, transforma por lotes, cambia consumidores y retira lo viejo tras comprobarlo. Ensaya la migración y su recuperación con datos representativos.','¿Qué despliegue reduce una ruptura de contrato?','Añadir campo compatible, migrar y retirar después','Renombrar todo sin transición','Borrar la tabla y esperar que se repueble','La convivencia temporal permite despliegues graduales.',true),
],`SELECT id, created_at FROM events\nWHERE (created_at,id) > ($1,$2)\nORDER BY created_at,id LIMIT 1000;\n-- Persistir el último cursor solo tras completar el lote.`,['Expandir esquema compatible','Migrar por lotes','Cambiar consumidores','Contraer tras verificar'],
 'Una tabla de transacciones crece a cien millones de registros y un cambio de columna no puede detener el servicio.',
 'Diseña el procesamiento por cursor, los checkpoints y una migración compatible. Explica cuándo no elegirías particionamiento y cómo tratarías el retraso de réplicas.',
 {code:'const rows = await db.query("SELECT * FROM huge_table");',question:'¿Cuál es el primer riesgo operativo?',options:['Uso de memoria y transferencia sin límite','Paginación implícita','Checkpoint automático'],answer:0,why:'Un resultado completo no limita recursos ni facilita recuperación.'});
lesson(4,'Colas, Redis y presión de trabajo','Coordinar productores y consumidores con capacidad finita.',[
 concept('Colas','Una cola desacopla ritmos, pero no crea capacidad infinita. Mide profundidad y antigüedad del mensaje más viejo. Aplica límites y backpressure cuando la entrada supera la salida.','¿Qué señal muestra trabajo cada vez más atrasado?','Antigüedad creciente y salida menor que entrada','Solo cantidad de servidores','Color de los mensajes','La edad muestra impacto, incluso con profundidad moderada.'),
 concept('ACK y DLQ','Confirma tras completar el efecto durable. Reintenta errores temporales con límite; envía mensajes irrecuperables a una DLQ con causa y mecanismo de reenvío seguro.','¿Qué haces con un payload permanentemente inválido?','Aislarlo con causa, sin reintentos infinitos','Reintentarlo sin límite','Confirmarlo como procesado correctamente','El fallo permanente necesita intervención o corrección.',true),
 concept('Redis','Redis puede servir como caché o coordinación temporal. Define TTL, invalidación y qué ocurre si cae. No conviertas una caché descartable en la única evidencia de un pago o de su deduplicación.','¿Dónde conservarías la evidencia definitiva de un cobro?','En almacenamiento durable con restricciones','Solo en una clave con TTL corto','En memoria del worker','La caché no sustituye el registro de negocio.',true),
 concept('Concurrencia acotada','Más workers pueden saturar una base o un proveedor. Ajusta concurrencia y prefetch a la dependencia más lenta. Usa métricas de latencia, límites y errores para decidir.','El proveedor admite 20 solicitudes simultáneas. ¿Qué haces?','Acotar concurrencia y gestionar espera','Lanzar miles de promesas simultáneas','Eliminar timeouts','La capacidad del cuello de botella determina el límite.'),
],`async function handle(message) {\n  await persistOnce(message.id, message.payload);\n  channel.ack(message);\n}\n// Definir prefetch y rutas de error/DLQ fuera de este fragmento.`,['Recibir con concurrencia acotada','Validar y deduplicar','Persistir efecto','ACK o ruta de fallo'],
 'Una importación produce tareas más rápido de lo que el proveedor puede atenderlas.',
 'Define prefetch, reintentos con backoff y jitter, criterios de DLQ y un procedimiento de reenvío sin duplicar efectos.',
 {code:'channel.ack(msg); await saveResult(msg);',question:'¿Qué ocurre si el proceso cae entre ambas líneas?',options:['Se puede perder el trabajo confirmado antes de persistir','La cola garantiza reconstruir el resultado','El ACK deshace la caída'],answer:0,why:'El broker ya puede considerar terminado el mensaje.'});
lesson(4,'Sagas, reintentos y circuit breakers','Diseñar recuperación entre servicios autónomos.',[
 concept('Sagas','Una saga coordina pasos locales y compensaciones de negocio. Una compensación no es un rollback físico universal: devolver un pago puede ser otro evento con reglas y plazos propios.','¿Qué representa una compensación?','Una acción de negocio que contrarresta un efecto','Deshacer mágicamente todas las bases','Una transacción global automática','Los efectos externos pueden requerir acciones nuevas.'),
 concept('Reintentos','Reintenta solo si el error es temporal y el efecto es seguro de repetir. Backoff y jitter reducen sincronización. Limita intentos y presupuesto temporal; un timeout deja incierto el efecto remoto.','¿Qué necesitas antes de repetir una petición de cobro?','Idempotencia o reconciliación del efecto incierto','Solo un bucle de reintentos','Ignorar el timeout','Repetir una escritura externa puede duplicar un cargo.',true),
 concept('Circuit breaker','Abre el circuito ante fallos suficientes y permite sondeos controlados para recuperarse. No reemplaza timeouts, validación ni límites. Distingue proveedor caído de entrada inválida.','¿Qué hace un circuito abierto?','Evita nuevas llamadas durante una ventana controlada','Repara al proveedor','Garantiza que ninguna petición fallará','Su objetivo es limitar daño y dar tiempo de recuperación.'),
 concept('Decisión de arquitectura','La comunicación asíncrona aporta autonomía y tolerancia a latencia, a cambio de consistencia y operación más complejas. Una llamada síncrona corta puede ser la opción adecuada para una respuesta inmediata.','¿Cuándo evitarías una saga?','Cuando una transacción local simple cubre el caso','Siempre que exista más de una tabla','Para cualquier pago sin analizar límites','No añadas coordinación distribuida si no hay una necesidad real.'),
],`for (let attempt=0; attempt<MAX_ATTEMPTS; attempt++) {\n  try { return await provider.call({idempotencyKey}); }\n  catch (e) {\n    if (!isTransient(e) || attempt===MAX_ATTEMPTS-1) throw e;\n    await sleep(backoffWithJitter(attempt));\n  }\n}`,['Detectar fallo','Clasificar e inspeccionar efecto','Reintentar con presupuesto','Compensar o escalar'],
 'Una reserva cobra, asigna inventario y confirma un envío en sistemas diferentes.',
 'Diseña una saga con estados, compensaciones e identificadores estables. Explica qué harías si una compensación también falla.',
 {code:'while(true) { try { await charge(); break; } catch {} }',question:'¿Por qué es peligroso?',options:['Puede duplicar efectos y reintentar sin límites ni clasificación','Garantiza disponibilidad infinita','Es un circuit breaker completo'],answer:0,why:'No hay presupuesto, idempotencia ni diagnóstico.'});
lesson(4,'Eventos y consistencia distribuida','Distinguir entrega, orden e identidad de negocio.',[
 concept('Eventos','Un evento cuenta un hecho pasado con identidad, tipo y versión de esquema. Un comando solicita una acción. Separarlos aclara quién decide y cómo evolucionan consumidores.','¿Qué nombre describe un hecho?','PaymentConfirmed','PleasePayNow como hecho confirmado','Un JSON sin tipo','El evento representa algo que ya ocurrió.'),
 concept('Consistencia eventual','Los componentes pueden observar estados distintos mientras se propagan eventos. La interfaz debe comunicar pendiente y permitir seguimiento. Define invariantes que nunca pueden relajarse y dónde se protegen.','¿Qué comunica una lectura aún no actualizada?','Estado pendiente y posibilidad de consultar después','Un éxito inventado','Que los datos nunca serán consistentes','La experiencia debe reflejar el estado conocido.'),
 concept('Orden y versiones','Los eventos pueden llegar duplicados o fuera de orden. Usa versiones o precondiciones para impedir que un evento antiguo sobrescriba un estado más nuevo. Un timestamp de reloj no siempre es una secuencia fiable.','¿Cómo evitas que una versión 2 reemplace la 3?','Comparación de versión al actualizar','Confiando solo en el orden de red','Eliminando todos los mensajes tardíos sin revisar','La precondición protege el estado frente a reordenamiento.'),
 concept('Idempotencia distribuida','La identidad del efecto debe sobrevivir a procesos y despliegues. Almacena la deduplicación en el mismo límite transaccional que el efecto local. Un candado temporal por sí solo no garantiza que el trabajo no se repita tras expirar.','¿Qué protege al consumidor de reentregas?','Restricción durable por evento junto al efecto','Un booleano en memoria','Un lock sin registrar resultado','La evidencia durable debe permanecer tras un reinicio.',true),
],`UPDATE projections SET state=$1, version=$2\nWHERE entity_id=$3 AND version < $2\nRETURNING version;\n-- Definir política para versiones faltantes y reconciliación.`,['Identificar evento y versión','Deduplicar','Comprobar transición','Persistir proyección'],
 'Webhooks de un proveedor llegan repetidos y la confirmación puede recibirse antes que un estado intermedio.',
 'Define el esquema de un evento y la política de orden, deduplicación y reconciliación de una proyección. Explica los estados que mostraría React.',
 {code:'projection.state = incoming.state; // sin versión',question:'¿Qué puede salir mal?',options:['Un evento antiguo puede hacer retroceder el estado','El orden de entrega está garantizado por HTTP','Nunca habrá eventos repetidos'],answer:0,why:'La red no garantiza un orden global de hechos.'});
lesson(5,'Modelos, tokens y límites','Decidir qué parte de un problema conviene delegar a un modelo.',[
 concept('Predicción y verdad','Un modelo de lenguaje produce continuaciones plausibles, no una prueba automática de hechos. Puede ser útil clasificando o redactando, pero una regla contable exacta debe seguir siendo determinista. Diseña cómo detectar respuestas incorrectas.','¿Qué tarea conservarías como regla determinista?','Cálculo y validación exacta del saldo','Redacción de un resumen revisable','Clasificación sugerida de un ticket','Una decisión de integridad no debe depender de texto probabilístico.',true),
 concept('Tokens y contexto','Los modelos procesan tokens y tienen límites de contexto y salida. Un documento largo puede requerir partición, recuperación o resumen. Más contexto no garantiza que toda la información se use correctamente; mide con casos representativos.','¿Qué haces con documentos que exceden el contexto?','Recuperar o dividir con una estrategia evaluada','Truncar sin avisar y asumir cobertura total','Prometer memoria ilimitada','Hay que conservar evidencia y medir lo que se pierde.'),
 concept('Aprendizaje y evaluación','Entrenar ajusta parámetros; inferir usa un modelo ya entrenado. Separa conjuntos de desarrollo y prueba y evita que ejemplos de evaluación contaminen el entrenamiento o el prompt de referencia.','¿Por qué separar un conjunto de prueba?','Para medir generalización sobre ejemplos no usados para ajustar','Para garantizar una nota perfecta','Para reducir el número de usuarios','La evaluación necesita evidencia independiente.'),
 concept('Privacidad','Minimiza datos antes de enviar una solicitud. Verifica retención, región y acceso del proveedor. Quitar el nombre no siempre anonimiza un expediente; combinación de campos puede reidentificar.','¿Qué enviarías a un clasificador de tickets?','Solo los campos necesarios, con datos sensibles minimizados','Toda la base con tokens incluidos','Credenciales para que el modelo consulte libremente','La utilidad debe equilibrarse con minimización y permisos.',true),
],`const input = redactSensitiveFields(ticket);\nconst prediction = await classifier.predict(input);\nif (prediction.needsReview) await queueHumanReview(ticket.id);\n// Una etiqueta sugerida no ejecuta por sí misma una acción irreversible.`,['Definir objetivo medible','Minimizar entrada','Ejecutar inferencia','Evaluar y decidir acción'],
 'Una empresa quiere clasificar incidencias y sugerir prioridad sin inventar hechos ni revelar datos privados.',
 'Separa las decisiones deterministas de las probabilísticas. Diseña un conjunto de evaluación y una política de datos para el clasificador.',
 {code:'if (llmSaysPaid) order.state = "paid";',question:'¿Cuál es el error crítico?',options:['Se usa una afirmación del modelo como evidencia financiera','El modelo siempre consulta la base','La salida de texto equivale a un comprobante'],answer:0,why:'Un estado financiero requiere evidencia de un sistema autorizado.'});
lesson(5,'Salidas estructuradas y herramientas','Convertir texto generado en propuestas verificables.',[
 concept('Contratos de salida','Un esquema restringe la estructura esperada; no demuestra que los valores sean verdaderos ni que cumplan el negocio. Valida estructura, rangos y referencias antes de usar una respuesta.','¿Qué demuestra una salida que cumple un esquema?','Su estructura, no la veracidad de cada valor','Que toda decisión es correcta','Que existe autorización para ejecutarla','Conformidad y verdad son garantías diferentes.'),
 concept('Tool calling','El modelo puede proponer una herramienta y argumentos. Tu servidor verifica identidad, permisos, esquema y límites antes de ejecutar. La herramienta no hereda autoridad ilimitada por aparecer en un prompt.','El modelo propone borrar una cuenta. ¿Qué decide la ejecución?','La política del servidor y la autorización requerida','Solo la seguridad expresada en el prompt','El nombre de la herramienta','La autoridad reside fuera del modelo.',true),
 concept('Prompt injection','Documentos y mensajes recuperados son datos no confiables. Pueden contener instrucciones para exfiltrar secretos. Separa instrucciones de contenido y limita herramientas; no dependas solo de pedir al modelo que ignore ataques.','Un documento pide enviar una API key a otra URL. ¿Qué haces?','Tratarlo como contenido no autorizado y bloquear el efecto','Ejecutarlo por estar en el contexto','Añadir la clave al prompt para ayudar','El contenido recuperado no concede permisos.',true),
 concept('Validación por capas','Valida entrada y salida, aplica reglas del dominio y registra decisiones sin secretos. Para efectos irreversibles exige confirmación o revisión según el riesgo. Un esquema válido no autoriza un destino externo.','¿Qué comprobación sigue a validar los argumentos?','Permisos y reglas sobre los recursos concretos','Ninguna: JSON válido equivale a autorización','Confiar en cualquier URL incluida','El contrato de datos no reemplaza la política de ejecución.'),
],`const proposed = validateToolArguments(modelResponse);\nawait policy.authorize(actor, proposed.action, proposed.resource);\nconst result = await tools.execute(proposed, { timeoutMs: 3000 });\nawait audit.record({ actor: actor.id, action: proposed.action });`,['Interpretar propuesta','Validar argumentos','Autorizar y limitar','Ejecutar y auditar'],
 'Un asistente empresarial puede consultar estados y proponer cambios, pero no debe modificar cuentas por instrucciones de un ticket.',
 'Diseña dos herramientas: una de lectura y otra con efecto. Define esquemas, permisos, límites y una prueba de inyección desde un documento.',
 {code:'await tools[model.name](model.arguments);',question:'¿Qué falta?',options:['Allowlist, validación y autorización antes de ejecutar','Solo mostrar un spinner','Dar al modelo una clave de administrador'],answer:0,why:'La selección del modelo es una propuesta, no un permiso.'});
lesson(5,'RAG, embeddings y evaluaciones','Responder con evidencia recuperada y medir sus fallos.',[
 concept('Embeddings','Un embedding representa similitud según un modelo, no verdad ni permisos. La distancia útil depende del dominio y del modelo. Guarda versión y metadatos para poder reconstruir el índice.','¿Qué indica una similitud vectorial alta?','Cercanía representacional, no veracidad garantizada','Que el usuario tiene acceso','Que el documento está vigente','La recuperación puede encontrar texto parecido pero incorrecto.'),
 concept('Recuperación','Divide documentos con límites coherentes, conserva referencias y filtra por permisos antes de devolver contexto. Combina búsquedas léxicas y semánticas cuando el dominio requiere identificadores exactos.','¿Cuándo filtras por organización?','Durante la recuperación antes de exponer contexto','Después de mostrar el documento','Solo al crear el índice por primera vez','La recuperación también es un control de acceso.',true),
 concept('Generación con evidencia','RAG añade material recuperado al contexto; no elimina alucinaciones. Exige referencias verificables y una respuesta de insuficiencia cuando falta evidencia. No conviertas una cita inventada en prueba.','¿Qué respuesta es adecuada si no hay evidencia?','Reconocer la insuficiencia y pedir o buscar información autorizada','Inventar una fuente plausible','Afirmar certeza sin contexto','La ausencia de evidencia debe ser un resultado posible.'),
 concept('Evaluación','Mide recuperación y respuesta por separado: relevancia de documentos, fidelidad, corrección, latencia y coste. Incluye preguntas sin respuesta y documentos maliciosos. La evaluación humana calibra casos ambiguos.','¿Qué conjunto detecta límites reales del RAG?','Casos respondibles, sin evidencia, ambiguos y adversariales','Solo preguntas copiadas de los ejemplos','Una sola demo feliz','Las pruebas deben cubrir fallo y abstención.'),
],`const hits = await search({ query, tenantId: actor.tenantId });\nconst evidence = hits.filter(canRead.bind(null, actor));\nif (!evidence.length) return { status: 'insufficient_evidence' };\nreturn answerWithReferences(question, evidence);`,['Autorizar consulta','Recuperar y filtrar','Generar con referencias','Evaluar y permitir abstención'],
 'Un buscador responde sobre manuales internos de distintas empresas y versiones de un mismo procedimiento.',
 'Diseña el esquema de documentos, permisos, partición e índice. Propón diez casos de evaluación, incluidos falta de evidencia e inyección.',
 {code:'const docs = await vectorSearch(query); // sin tenant ni permisos',question:'¿Cuál es el riesgo?',options:['Recuperar información de otra organización','Mayor exactitud por compartir todos los datos','Autorización automática por similitud'],answer:0,why:'La búsqueda debe respetar acceso y pertenencia.'});
lesson(6,'Flujos basados en eventos','Automatizar procesos con estados y puntos de intervención.',[
 concept('Orquestación','Un orquestador mantiene el estado del proceso y decide el siguiente paso. Evita lógica dispersa en callbacks sin identidad común. Cada transición debe poder repetirse o recuperarse de forma segura.','¿Qué necesita un flujo recuperable?','Identidad, estado durable y transiciones definidas','Solo callbacks en memoria','Un cron que repite todo siempre','La recuperación requiere saber qué quedó confirmado.'),
 concept('Intervención humana','Modela la revisión como estado explícito, con responsable, fecha y datos visibles. Una decisión pendiente no es un éxito. Define qué ocurre si vence el plazo sin respuesta.','¿Qué estado asignas a una aprobación sin responder?','Pendiente de revisión','Aprobado por silencio sin regla','Finalizado correctamente','No se puede inferir una aprobación no recibida.',true),
 concept('Eventos de negocio','Los eventos disparan acciones a partir de hechos confirmados. Comprueba identidad, firma y deduplicación de webhooks. Un mensaje entrante no es confiable por afirmar que viene de un proveedor.','¿Qué validas en un webhook?','Firma, alcance y duplicados según el contrato','Solo que tenga JSON','El nombre del remitente en el body','El límite de entrada debe validar su autenticidad.',true),
 concept('Larga duración','Persistir checkpoints evita mantener una petición HTTP abierta durante horas. El cliente consulta estado o recibe notificaciones apropiadas. Diseña vencimientos, cancelación y compensación.','Un proceso tarda un día. ¿Qué devuelve el API inicial?','Identificador y estado consultable del trabajo','Una conexión bloqueada sin límite','Un éxito antes de ejecutarlo','La aceptación de trabajo no equivale a su finalización.'),
],`await workflows.transition(id, 'awaiting_review', {\n  reviewerGroup: 'operations', deadline: reviewDeadline\n});\n// Una acción autenticada registrará aprobación o solicitud de cambios.`,['Registrar intención','Ejecutar paso durable','Esperar decisión si hace falta','Reanudar desde checkpoint'],
 'La clasificación automática de una incidencia propone una acción que requiere autorización de operaciones.',
 'Modela un flujo de clasificación, revisión y ejecución con vencimientos. Explica cómo retomarías el trabajo después de reiniciar todos los procesos.',
 {code:'setTimeout(() => approveAutomatically(), 86400000);',question:'¿Qué limitación tiene como única persistencia?',options:['El proceso puede reiniciarse y perder el temporizador y su contexto','Es un registro durable de aprobación','Garantiza intervención humana'],answer:0,why:'Una espera de larga duración necesita estado durable y política explícita.'});
lesson(6,'Agentes y MCP con permisos acotados','Conectar herramientas sin delegar autoridad ilimitada.',[
 concept('Agente acotado','Un agente combina un modelo, estado y herramientas para perseguir una tarea. Define condiciones de parada, presupuesto y acciones permitidas. Una secuencia determinista puede ser más adecuada si el proceso no requiere decisión abierta.','¿Cuándo evitarías un agente?','Cuando un flujo determinista y verificable basta','Siempre que exista una API','Solo cuando no haya interfaz gráfica','La autonomía añade complejidad y variabilidad.'),
 concept('MCP','MCP estandariza cómo exponer herramientas y contexto; no reemplaza autorización del servidor ni valida que una herramienta sea segura. Una conexión solo debe ofrecer las capacidades necesarias para esa tarea.','¿Qué no garantiza MCP por sí solo?','Que toda llamada esté autorizada sobre los datos del usuario','Una forma de describir herramientas','Un contrato de interacción','La autorización sigue siendo responsabilidad del servicio.',true),
 concept('Permisos mínimos','Separa herramientas de consulta y de escritura y limita recursos por usuario/empresa. El agente no debe recibir credenciales globales para resolver una consulta local. Registra el actor y la decisión de permiso.','¿Qué acceso darías a un asistente de consulta de tickets?','Lectura de tickets autorizados para el actor','Administrador de toda la base','Acceso a contraseñas para ahorrar pasos','El permiso debe corresponder a la necesidad.',true),
 concept('Presupuesto','Acota herramientas, tiempo, tokens y coste por tarea. Detén ciclos sin progreso y conserva un estado que permita al usuario entender qué ocurrió. No continúes indefinidamente por una instrucción dentro de un documento.','¿Qué control evita bucles costosos?','Límites y condición de parada verificable','Más herramientas sin métricas','Reintentos infinitos del modelo','Un objetivo necesita un presupuesto y un criterio de terminación.'),
],`if (!allowedTools.has(call.name)) throw forbidden();\nawait authorizeResource(actor, call.arguments);\nawait budget.consume({ calls: 1 });\nreturn executeWithTimeout(call);`,['Definir objetivo y presupuesto','Exponer herramientas mínimas','Autorizar cada llamada','Detener y registrar resultado'],
 'Un agente puede leer incidencias, sugerir una respuesta y crear una propuesta de cambio para revisión.',
 'Diseña un servidor MCP con dos herramientas, su alcance por empresa y un presupuesto de ejecución. Explica cómo bloquearías una instrucción maliciosa de un ticket.',
 {code:'const tools = exposeAllDatabaseAdminActions();',question:'¿Qué principio incumple?',options:['Mínimo privilegio y separación de capacidades','Una garantía de seguridad por usar MCP','Presupuesto de solo lectura'],answer:0,why:'Exponer toda la autoridad de la base amplía innecesariamente el daño posible.'});
lesson(6,'Recuperación y coordinación inteligente','Escoger actores y reanudar trabajo sin duplicar efectos.',[
 concept('Coordinación','Varios agentes aportan valor si separan capacidades verificables. También añaden mensajes, estados y puntos de fallo. Compara con un solo agente o workflow antes de repartir responsabilidades.','¿Qué justifica varios agentes?','Roles especializados con contratos y beneficio medido','La existencia de varios prompts','Necesitar más complejidad visual','La coordinación debe tener una ventaja verificable.'),
 concept('Checkpoints','Guarda la intención, resultado de herramientas y versión del proceso. Al recuperar, comprueba si el efecto anterior se confirmó antes de volver a ejecutarlo. Un historial de chat solo no reemplaza un registro de negocio.','¿Qué revisas tras una caída durante un cobro?','La evidencia durable del efecto y su clave idempotente','Solo la última frase del modelo','Que el proceso tenga el mismo nombre','La reanudación debe reconciliar efectos inciertos.',true),
 concept('Contratos entre actores','Cada actor produce una salida validada, con autoría y estado. Una opinión no verificada de otro agente sigue siendo una propuesta, especialmente si activa una escritura o afecta integridad.','¿Cómo tratas una propuesta de otro agente?','Validando contrato, evidencia y permisos antes de actuar','Como una orden administrativa infalible','Como sustituto de una transacción','La confianza no se hereda por ser otro componente automático.'),
 concept('Operación','Mide tasa de éxito, intervención humana, coste y ciclos por tarea. Conserva evidencia suficiente para reproducir un fallo sin guardar datos sensibles innecesarios. Diseña cancelación y apagado seguro.','¿Qué métrica indica trabajo automático inútil?','Muchos ciclos y llamadas sin progreso en el objetivo','Solo número de agentes creados','Cantidad de colores en el diagrama','La actividad no equivale a resultado.'),
],`const checkpoint = await store.load(runId);\nconst effect = await ledger.find(checkpoint.effectKey);\nif (effect?.confirmed) return resumeAfterEffect(checkpoint, effect);\nreturn reconcileOrRetry(checkpoint);`,['Cargar checkpoint','Reconciliar efecto anterior','Elegir siguiente acción permitida','Persistir avance'],
 'Un flujo de conciliación, clasificación y comunicación se ejecuta durante horas y debe tolerar despliegues.',
 'Compara un workflow y una solución multiagente para el mismo caso. Define contratos, puntos de recuperación y una prueba de cancelación.',
 {code:'await repeatAllPreviousToolCalls(history);',question:'¿Por qué es peligroso?',options:['Puede repetir efectos ya confirmados','El historial hace todo idempotente','Una herramienta nunca tiene efectos'],answer:0,why:'La recuperación debe distinguir lectura, intención y efecto confirmado.'});
lesson(7,'Docker, Git y entrega continua','Entregar versiones reproducibles y recuperables.',[
 concept('Imagen reproducible','Una imagen fija dependencias y proceso de arranque; no elimina la necesidad de configurar secretos, permisos y recursos. Construye una vez y promueve el artefacto probado. Evita incluir archivos de entorno privados en la imagen.','¿Qué debes excluir de la imagen?','Credenciales y archivos privados de entorno','El código de aplicación necesario','Un lockfile de dependencias','Los secretos deben inyectarse de forma controlada.',true),
 concept('Pipeline','Un pipeline ejecuta validaciones antes de desplegar: análisis, pruebas, build y pruebas de humo. Un build exitoso no demuestra que permisos ni migraciones sean correctos.','¿Qué prueba complementa el build?','Una solicitud autenticada y otra no autorizada contra la versión desplegada','Solo que exista un archivo dist','Solo que npm no devuelva error','Verifica comportamiento y límites de acceso.'),
 concept('Git y revisión','Usa ramas y cambios revisables con propósito concreto. Incluye evidencia y riesgos de migración en la revisión. Un commit no es una copia de seguridad completa de los datos de producción.','¿Qué debe explicar una revisión con cambio de datos?','Compatibilidad, validación y recuperación','Solo el número de líneas','Que compila en un equipo','Los revisores necesitan evaluar el efecto operativo.'),
 concept('Despliegue gradual','Separa despliegue de activación y vigila señales antes de aumentar tráfico. Un rollback de código no deshace una migración incompatible ni un efecto externo. Planifica ambas recuperaciones.','¿Qué no resuelve necesariamente un rollback de código?','Deshacer una transformación irreversible de datos','Volver a un artefacto anterior','Reducir exposición de una nueva función','Los cambios de datos tienen su propio plan.'),
],`# Fragmento ilustrativo; revisar dependencias y usuario de runtime\nFROM node:24-slim\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci --omit=dev\nCOPY . .\nUSER node\nCMD ["node", "server.js"]`,['Validar cambio','Construir artefacto','Desplegar gradualmente','Verificar y promover o revertir'],
 'Una plataforma cloud recibe varias entregas por día y no puede romper contratos de consumidores antiguos.',
 'Diseña un pipeline con controles y un despliegue de migración expandir-contraer. Explica qué incluirías en .dockerignore y cómo recuperarías una versión.',
 {code:'COPY .env.production /app/.env',question:'¿Qué riesgo introduce?',options:['Distribuir secretos dentro del artefacto','Un gestor de secretos automático','Un backup seguro de credenciales'],answer:0,why:'Las capas e imágenes pueden conservar y distribuir el archivo.'});
lesson(7,'OpenTelemetry y pruebas de carga','Observar recorridos completos y validar capacidad.',[
 concept('Trazas','Una traza enlaza spans de un recorrido; propaga contexto entre API, cola y worker. El muestreo y la cardinalidad afectan coste y utilidad. No conviertas cada dato personal en una etiqueta.','¿Qué permite relacionar API y worker?','Contexto de traza propagado en el mensaje','El nombre de una función sin correlación','Un timestamp sin identidad común','La propagación conecta operaciones distribuidas.'),
 concept('Métricas y objetivos','Define latencia, tasa de error y disponibilidad desde la experiencia del usuario. Un promedio puede ocultar colas largas; revisa percentiles y límites. Un objetivo necesita una ventana y criterio de medición.','¿Qué oculta a menudo una latencia promedio?','Usuarios con respuestas mucho más lentas','El número total de servidores','La versión del repositorio','Los percentiles revelan la cola de distribución.'),
 concept('Carga','Una prueba de carga necesita patrón de llegada, mezcla de operaciones y datos representativos. Diferencia prueba de estrés de operación normal. Observa la dependencia limitante, no solo CPU de la aplicación.','¿Qué hace representativa una prueba?','Tráfico y datos semejantes al caso esperado, con métricas','Una llamada repetida contra una tabla vacía','Solo medir el tamaño del bundle','La carga real incluye mezcla, concurrencia y datos.'),
 concept('Datos sensibles','Filtra headers, tokens y cuerpos antes de enviar telemetría. Un proveedor de observabilidad es otra frontera de datos. Define retención y acceso para no crear una copia innecesaria de información privada.','¿Qué debe evitar un span?','Registrar la contraseña o token completo','Registrar duración','Registrar un nombre de operación controlado','Los secretos no pertenecen a la telemetría.',true),
],`const span = tracer.startSpan('reconciliation.batch');\ntry { await runBatch(); span.setStatus({code: 1}); }\ncatch (error) { span.setStatus({code: 2}); throw error; }\nfinally { span.end(); }\n// Propagar contexto y filtrar datos en la configuración completa.`,['Definir objetivo observable','Instrumentar recorrido','Generar carga representativa','Analizar cuello de botella'],
 'La p95 de un endpoint empeora cuando coinciden importaciones y consultas del dashboard.',
 'Diseña un experimento con carga mixta, métricas y trazas. Explica cómo separarías lentitud de base, proveedor y cola.',
 {code:'span.setAttribute("authorization", req.headers.authorization);',question:'¿Qué error hay?',options:['Exponer una credencial en telemetría','Una práctica obligatoria para correlación','Una anonimización automática'],answer:0,why:'El contexto técnico no requiere guardar secretos.'});
lesson(7,'Disponibilidad, seguridad y coste','Operar con presupuestos y modos de fallo explícitos.',[
 concept('Alta disponibilidad','Replica procesos y elimina puntos únicos donde el objetivo lo exija. Define RTO y RPO: tiempo de recuperación y pérdida de datos tolerables. Tener dos servidores no demuestra que una restauración funcione.','¿Qué valida un plan de recuperación?','Un ejercicio de restauración con medición de RTO/RPO','Solo contratar otra máquina','Confiar en que hay backups sin probarlos','La recuperación necesita evidencia operativa.'),
 concept('Secretos y acceso','Usa mínimos privilegios, rotación y separación de entornos. Una clave de desarrollo no debe dar acceso a producción. Mantén verificación TLS y evita respuestas de error que filtren la configuración.','¿Qué aislamiento conviene entre pruebas y producción?','Credenciales y recursos con permisos separados','La misma cuenta administradora para todo','Secretos en el frontend para facilitar pruebas','Los fallos de prueba no deben comprometer producción.',true),
 concept('Coste','Mide coste por operación útil, almacenamiento, egress, modelo y telemetría. Una caché puede reducir llamadas pero añadir invalidación y operación. Optimiza según evidencia y sensibilidad de datos.','¿Qué métrica guía un producto sostenible?','Coste por operación exitosa junto a calidad y latencia','Solo coste de una máquina','Solo tokens totales sin resultado','El coste importa en relación con valor y calidad.'),
 concept('Degradación','Define qué puede funcionar sin una dependencia y qué debe detenerse. Un buscador puede indicar falta de resultados; un pago no debe inventar una confirmación si la fuente autorizada está caída.','¿Qué harías si no puedes confirmar un pago?','Mostrar estado pendiente y reconciliar','Marcar pagado para mejorar disponibilidad aparente','Borrar la operación','La disponibilidad no justifica romper integridad.',true),
],`if (!providerAvailable) {\n  await markPendingReconciliation(operationId);\n  return { status: 'pending', operationId };\n}\n// Nunca convertir una respuesta desconocida en un éxito financiero.`,['Definir objetivos y amenazas','Diseñar límites y redundancia','Probar fallos y restauración','Medir coste y ajustar'],
 'Una plataforma debe seguir mostrando información autorizada aunque una dependencia externa esté caída.',
 'Define modos de degradación, RTO/RPO y controles de secretos. Estima las categorías de coste y un experimento para reducir egress sin romper permisos.',
 {code:'catch { return { paid: true }; }',question:'¿Qué riesgo crea este fallback?',options:['Inventar un éxito que viola integridad','Una alta disponibilidad correcta','Una compensación verificada'],answer:0,why:'Un fallo de comunicación no es prueba de pago.'});
lesson(8,'Proyecto: una plataforma modular','Integrar interfaz, API y datos con contratos y ownership.',[
 concept('Alcance','Define actores, operaciones y amenazas antes de elegir infraestructura. Comienza con un monolito modular si cumple las restricciones. Documenta qué necesidad futura justificaría separar un servicio.','¿Qué va primero al diseñar el proyecto?','Requisitos e invariantes observables','Elegir microservicios por moda','Seleccionar todos los proveedores posibles','La arquitectura responde al problema.'),
 concept('Ownership','Cada dato y regla debe tener una autoridad. React muestra estados autorizados por el servidor. El usuario de la sesión determina pertenencia; no un identificador editable en el body.','¿Qué identifica al dueño de una operación?','El actor autenticado y las reglas del servidor','Un userId libre enviado por React','La dirección IP como permiso universal','El límite de autorización protege aislamiento.',true),
 concept('Datos','Modela usuarios, compañías, operaciones, eventos y auditoría con restricciones. Guarda migraciones y semillas reproducibles. Una semilla no debe borrar datos reales para actualizar un temario o configuración.','¿Cómo actualizas configuración sin perder historial?','Upsert versionado y migración compatible','TRUNCATE de toda la base','Recrear usuarios en cada despliegue','Las actualizaciones deben preservar identidades e historia.'),
 concept('Contrato de interfaz','Distingue cargando, vacío, error, pendiente y éxito. Permite consultar un trabajo sin mantener una conexión abierta. Usa identificadores estables y evita afirmar resultados aún no confirmados.','Un trabajo fue aceptado pero no ejecutado. ¿Qué muestra React?','Pendiente con identificador de seguimiento','Completado con una nota inventada','Un error sin posibilidad de consulta','La interfaz representa el estado conocido.'),
],`type JobView =\n | {status:'pending'; id:string}\n | {status:'done'; id:string; result:Result}\n | {status:'failed'; id:string; errorCode:string};`,['Definir casos de uso','Modelar datos y permisos','Implementar API y UI','Probar integración y aislamiento'],
 'Construye una plataforma de conciliación y clasificación de incidencias para varias compañías.',
 'Entrega el diagrama, contratos REST, migraciones y una pantalla de seguimiento. Incluye al menos una prueba que intente acceder a otra empresa.',
 {code:'GET /jobs/:id // devuelve el job sin comprobar ownership',question:'¿Qué prueba falta?',options:['Acceso cruzado entre actores sin permiso','Solo medir colores y tipografía','Que todos los jobs tengan la misma empresa'],answer:0,why:'El identificador de una ruta no es autorización.'});
lesson(8,'Proyecto: IA y automatización recuperable','Integrar clasificación con un proceso verificable y humano.',[
 concept('Separar propuesta y efecto','La IA propone una etiqueta o acción; el dominio valida y un actor autorizado decide el efecto. Guarda versión del modelo, entrada minimizada y evidencia suficiente para revisión.','¿Qué activa una escritura sensible?','Validación de negocio y permiso explícito requerido','Una frase convincente del modelo','Cualquier etiqueta de prioridad alta','La salida probabilística no concede autoridad.',true),
 concept('Pipeline','Usa Outbox para iniciar el trabajo, workers con deduplicación y un estado de revisión cuando sea necesario. Limita reintentos y conserva errores diagnósticos. No escondas trabajo perdido con un éxito visual.','¿Qué une la creación de una incidencia y su tarea?','Una transacción con evento Outbox','Dos llamadas independientes sin registro','Un temporizador en React','La evidencia durable permite recuperar la automatización.'),
 concept('Evaluación','Compara con una línea base determinista. Evalúa clasificación, abstención, errores críticos, coste y latencia antes de automatizar más acciones. El modelo más caro no siempre aporta una mejora relevante.','¿Cómo justificas el uso de IA?','Con una evaluación frente a una línea base y criterios de negocio','Solo con una demo exitosa','Por el nombre comercial del modelo','La arquitectura necesita evidencia de beneficio.'),
 concept('Revisión y auditoría','Guarda quién revisó, qué evidencia vio y qué decidió. La revisión pendiente no desbloquea acciones que requieren aprobación. Permite pedir cambios y reanudar con nueva evidencia.','¿Qué debe contener una aprobación?','Revisor autorizado, decisión, fecha y evidencia','Solo un booleano enviado por el cliente','Una selección aleatoria','La auditoría permite atribuir y revisar decisiones.',true),
],`await transaction(async tx => {\n  await tx.insert('tickets', ticket);\n  await tx.insert('outbox', {type:'TicketCreated', ticketId:ticket.id});\n});\n// Worker: clasifica, valida y deja awaiting_review si corresponde.`,['Persistir ticket + evento','Clasificar con límites','Validar y revisar','Ejecutar y auditar'],
 'La plataforma sugiere qué incidencias requieren conciliación y prepara acciones sin ejecutarlas indebidamente.',
 'Implementa un flujo de punta a punta en diseño y código. Define las pruebas de duplicados, caída del modelo, inyección y revisión rechazada.',
 {code:'if (prediction.priority === "high") await refundAll();',question:'¿Qué control falta?',options:['Autorización y verificación del efecto con revisión apropiada','Una prioridad aún más alta','Dar acceso global al clasificador'],answer:0,why:'Una clasificación no es permiso para reembolsar.'});
lesson(8,'Defender una arquitectura empresarial','Justificar compromisos y demostrar tolerancia a fallos.',[
 concept('Decisiones','Un ADR registra contexto, opciones, decisión y consecuencias. Explica por qué descartas una alternativa bajo las restricciones actuales y qué evidencia haría cambiar la decisión.','¿Qué hace útil un ADR?','Contexto, alternativas y consecuencias verificables','Solo una lista de herramientas','Afirmar que una tecnología siempre es mejor','Una decisión depende de condiciones y compromisos.'),
 concept('Evidencia','Defiende garantías con pruebas: concurrencia, aislamiento de usuarios, recuperación, carga y evaluación de IA. Una demo no demuestra comportamiento bajo fallos.','¿Qué evidencia respalda idempotencia?','Pruebas concurrentes y de recuperación verificando un solo efecto','Solo que un botón funcione','Un diagrama con una cola','Las garantías requieren experimentos relevantes.'),
 concept('Operación','Entrega runbooks, alertas accionables, límites y un plan de restauración. Define responsables y criterios de escalado. Un sistema difícil de diagnosticar no está listo solo por estar desplegado.','¿Qué convierte una alerta en accionable?','Síntoma, impacto y procedimiento de respuesta','Solo un mensaje de error sin contexto','Una notificación por cada log','La alerta debe ayudar a decidir una intervención.'),
 concept('Límites honestos','Distingue garantías implementadas, hipótesis y trabajo futuro. No prometas exactamente una ejecución global ni decisiones infalibles de IA. Declara qué requiere supervisión humana y cuándo debe detenerse el proceso.','¿Qué debe incluir la defensa final?','Límites y escenarios de fallo además del camino feliz','Garantías no probadas para convencer','Ocultar la necesidad de revisión','Una arquitectura confiable explicita dónde puede fallar.',true),
],`// Matriz de verificación del proyecto\nconst checks = [\n  'duplicate_request', 'worker_crash_after_commit',\n  'cross_tenant_access', 'provider_timeout',\n  'prompt_injection', 'restore_from_backup'\n];\n// Cada caso necesita resultado esperado y evidencia reproducible.`,['Presentar requisitos','Comparar alternativas','Mostrar pruebas y fallos','Defender límites y operación'],
 'Presenta la plataforma a un equipo que cuestiona coste, consistencia, aislamiento y uso de IA.',
 'Entrega un ADR, un diagrama completo, contratos, esquema, plan de pruebas, presupuesto y runbook. Explica un fallo de punta a punta y cómo recuperarlo sin duplicar efectos.',
 {code:'// Garantizamos que nunca habrá fallos ni respuestas incorrectas.',question:'¿Qué reemplazo es técnicamente defendible?',options:['Garantías acotadas, supuestos, pruebas y límites explícitos','Una promesa absoluta con más herramientas','Ocultar incidentes para mantener confianza'],answer:0,why:'La confiabilidad se demuestra dentro de un modelo de fallos, no por afirmaciones absolutas.'});

const analogies=[
 'Un número de recibo permite reconocer el mismo pago aunque alguien vuelva a pedir el comprobante. El Outbox es una bandeja durable de avisos pendientes.',
 'Una tarjeta identifica a quien entra; una llave decide qué sala puede abrir. Identidad y permiso no son la misma cosa.',
 'Un pedido pasa de recibido a preparado y entregado. Los estados registran hechos, no deseos; un seguimiento muestra dónde se detuvo.',
 'Una etiqueta dice qué debería contener una caja, pero todavía debes revisar lo que llega de fuera. Así se distinguen tipos y validación.',
 'Un enchufe separa el aparato de la instalación eléctrica. Un puerto define una capacidad y un adaptador conecta una tecnología concreta.',
 'Llamar a otra oficina requiere saber qué respuesta esperas, cuánto esperar y qué hacer si no responde. Una integración necesita ese mismo contrato.',
 'El índice de un libro ayuda a localizar un tema sin leer todas sus páginas. Cada índice cuesta espacio y mantenimiento.',
 'Dos personas no pueden llevarse el último ejemplar si cada una decide sin coordinarse. Las transacciones necesitan reglas de aislamiento.',
 'Mover un archivo por cajas pequeñas facilita retomar desde la última caja confirmada. Procesar lotes necesita límites y progreso durable.',
 'Una fila organiza pedidos pendientes; una copia de un menú acelera consultas. Cola y caché tienen objetivos diferentes.',
 'Si una reserva de viaje falla a mitad, cancelar pasos previos es una compensación, no borrar mágicamente toda la historia.',
 'Un aviso puede llegar dos veces o después de otro. Quien lo recibe debe saber reconocerlo y comprobar qué estado aplica.',
 'Una respuesta fluida no es una fuente de verdad: se parece a completar una frase según patrones, con límites que hay que comprobar.',
 'Una orden escrita con casillas obligatorias reduce ambigüedad, pero la persona que la recibe todavía debe comprobar permisos y contenido.',
 'Buscar páginas relevantes antes de contestar ayuda a aportar evidencia. Encontrar un texto no garantiza que sea correcto ni que pueda mostrarse.',
 'Un proceso de varias etapas necesita un cuaderno de qué se confirmó para continuar después de una interrupción.',
 'Un ayudante puede proponer acciones; sus herramientas funcionan dentro de permisos definidos, no de cualquier instrucción que encuentre.',
 'Una calculadora y una persona que revisa una excepción cumplen papeles distintos. Automatiza decisiones comprobables y acota las sensibles.',
 'Una tienda necesita luces, alarmas y plan de salida; un servicio necesita observación, límites y recuperación además del código.',
 'Una receta y sus ingredientes deben viajar juntos para reproducir un plato. Un artefacto probado también necesita configuración controlada.',
 'Practicar una evacuación permite medir cuánto tarda y qué falla. Una recuperación de datos también debe ensayarse.',
 'Antes de construir una casa, define qué debe sostener y bajo qué condiciones. Las garantías del proyecto son sus requisitos comprobables.',
 'Cada pieza de una bicicleta debe encajar con las demás. Integrar exige comprobar contratos y fallos en el recorrido completo.',
 'Explicar una decisión significa mostrar qué alternativas había y qué evidencia la sostiene, incluyendo lo que todavía no demuestra.',
];
